        thread_sum *= sycl::exp(old - thread_max);
        thread_sum += sycl::exp(v - thread_max);
      }
      float gmax = sycl::reduce_over_group(g, thread_max, sycl::maximum<float>{});
      thread_sum *= sycl::exp(thread_max - gmax);
